import { isGameTradition, type MythologyCatalogue, type MythologyEntity } from "./mythology-map.ts";

type Story = { story: string; detail: string };
const stories: Record<string, Story> = {
  "cosmic-egg": { story: "In one Orphic telling, the cosmic egg is generated by Chronos, Time. Phanes emerges from it. A very different way to begin a divine family.", detail: "This is creation followed by emergence, rather than an ordinary birth. The account is preserved through later witnesses." },
  phanes: { story: "Phanes emerges from the cosmic egg in the Orphic material quoted by later writers. His place near the beginning is one reason there is no single Greek creation story.", detail: "These are reported Orphic traditions, rather than another chapter of Hesiod. Their sources stay separate here." },
  "chronos-hades": { story: "In Hades II, Chronos is the Titan of Time and father to Hades, Zeus and Poseidon. Melinoë is trying to stop her own grandfather.", detail: "The game puts Time and the father of the Olympian brothers in one character. In the ancient accounts on this map, Chronos and Kronos have separate entries." },
  "chronos-time": { story: "Chronos here is Time, a primordial figure in the Orphic account reported by Damascius. He generates the egg from which Phanes emerges.", detail: "This is a separate entry from Kronos the Titan. The similar names can make an already complicated family rather confusing." },
  erebus: { story: "Erebus personifies Darkness. Hesiod places him with Nyx among the children of Chaos; together they become the parents of Aether and Hemera.", detail: "Darkness, Night, Day and the bright upper air all sit on the same family branch." },
  oceanus: { story: "Oceanus is one of the Titans. With Tethys, he stands at the head of the enormous family of Oceanids and river gods.", detail: "The poem mentions thousands, even though its named lists preserve only a selection. Each named river or nymph can have a separate entry." },
  tethys: { story: "Tethys is a Titan and, with Oceanus, a parent of the Oceanids and river gods. Water becomes an enormous divine family through this branch.", detail: "Tethys the Titan is a separate figure from Thetis, the Nereid associated with Achilles." },
  nymphs: { story: "Nymphs are the many divine nature figures associated with places such as trees, rivers and springs. This is a broad category, rather than one person with a single agreed parentage.", detail: "A dotted seal represents a collective. The individual names have their own family links and source passages." },
  nereids: { story: "The Nereids are the sea nymphs born to Nereus and Doris in Hesiod. Thetis and Amphitrite are among their more familiar names.", detail: "The poem says fifty, but the transmitted list used here yields 51 distinct names. That discrepancy stays visible in the coverage notes." },
  oceanids: { story: "The Oceanids belong to the vast family of Oceanus and Tethys. Names such as Metis and Styx have important individual connections within that much larger group.", detail: "Being part of a collective does not give every member the same story. Follow the individual names to see the differences." },
  harpies: { story: "The Harpies are winged beings born to Thaumas and Electra in Hesiod. Other tellings add different names to the family.", detail: "They have a genealogy and individual names, rather than being only a generic monster category." },
  moirai: { story: "The Moirai are the Fates: Clotho, Lachesis and Atropos. They are one of the clearest examples of a collective with individually named members.", detail: "Even Hesiod preserves different origins for the Fates, connecting them with Nyx in one passage and Zeus and Themis in another." },
  muses: { story: "The Muses are the nine daughters of Zeus and Mnemosyne in Hesiod. They connect divine genealogy with poetry and song.", detail: "Mnemosyne is Memory. Putting Memory beside the goddesses of poetry is a connection worth following." },
  "persephone-mortal-father-game": { story: "The game’s Persephone speaks of a mortal father, but the checked dialogue does not give him a name. This entry keeps him anonymous instead of borrowing a name from ancient genealogy.", detail: "This is a game-continuity difference. The ancient account naming Zeus remains in the other graph." },
  chaos: { story: "In Hesiod, the story opens with Chaos: a primordial opening, before the familiar divine family takes shape. Night and Darkness emerge from it. In Hades, Chaos remembers a world before Time and calls Nyx their child.", detail: "Coming first does not make Chaos everybody’s parent. Other ancient accounts begin differently." },
  gaia: { story: "Gaia is Earth herself, both the ground beneath the stories and a divine ancestor. She bears Sky and Sea and stands near the beginning of many family lines.", detail: "A personification can still be a god. The categories overlap from the very beginning." },
  uranus: { story: "Uranus is the Sky, born from Gaia in Hesiod. Their descendants include the Titans, placing him a generation before Kronos and Rhea.", detail: "Aphrodite’s sea-foam origin also connects to Uranus. Emergence is shown separately from ordinary birth." },
  kronos: { story: "Kronos belongs to the Titans and, with Rhea, fathers the generation of Zeus, Poseidon and Hades. Family succession is rather dramatic in this part of the mythology.", detail: "Kronos the Titan and Chronos as Time have separate entries here. Similar names, different source traditions." },
  rhea: { story: "Rhea is a Titan and the mother of the six divine siblings named by Hesiod: Hestia, Demeter, Hera, Hades, Poseidon and Zeus.", detail: "Her branch is a good place to see how closely connected the familiar Olympian names are." },
  hyperion: { story: "Hyperion is one of the Titans. In Hesiod, his children with Theia include Helios, Selene and Eos: Sun, Moon and Dawn.", detail: "Hades dialogue gives him another family connection: Hera, Hestia and Demeter call him their father." },
  zeus: { story: "Zeus is the Olympian ruler associated with the sky and thunder. In Hesiod, he is a son of Kronos and Rhea and a parent in many of the later divine families.", detail: "Recognise the thunderbolt. Then follow his children and see how quickly a simple family tree stops being simple." },
  hera: { story: "Hera is the queen of the gods, associated with marriage and her relationship with Zeus. She is much more than a supporting character in somebody else’s family drama.", detail: "Hesiod places her under Kronos and Rhea. The Hades dialogue instead names Hyperion as her father." },
  poseidon: { story: "Poseidon rules the sea and is also associated with earthquakes. In Hesiod’s genealogy he is a brother of Zeus and Hades.", detail: "His trident makes him easy to spot. The sea itself, its primordial beings and its many nymphs have their own entries too." },
  hades: { story: "Hades rules the realm of the dead. He belongs to the same divine generation as Zeus and Poseidon, but his stories lead into a different part of the world.", detail: "Hades rules the dead. Thanatos is Death itself. Same neighbourhood, very different job descriptions." },
  demeter: { story: "Demeter is associated with grain, harvest and the growing world. She is Persephone’s mother, which places her at the centre of one of the mythology’s most important family relationships.", detail: "Hesiod names Kronos and Rhea as her parents. Hades dialogue names Hyperion and Theia." },
  hestia: { story: "Hestia is the goddess of the hearth and the shared fire of a household. Her domain is quieter than thunder or war, but it belongs at the centre of everyday life.", detail: "Her ancient family includes Kronos and Rhea. Hades dialogue instead groups her with Hyperion’s daughters." },
  athena: { story: "Athena brings together wisdom, skilled crafts and war. The ancient accounts connect her birth with Zeus and Metis rather than giving her an ordinary two-parent birth story.", detail: "Look for the owl. Her broad range is a useful reminder that a deity rarely fits one neat god-of-something label." },
  apollo: { story: "Apollo is associated with music and prophecy. In Hesiod, Zeus and Leto are his parents, and Artemis is his sister.", detail: "His lyre is the visual cue here. Helios, the Sun, remains a separate figure rather than being silently folded into Apollo." },
  artemis: { story: "Artemis belongs to the wild world of hunting and animals. She and Apollo share Zeus and Leto as parents in the cited genealogy.", detail: "Her bow distinguishes her from Selene, the Moon. The two remain separate names in this catalogue." },
  ares: { story: "Ares is associated with war and battle. Hesiod names him among the children of Zeus and Hera.", detail: "A shield and spear identify his seal. Compare his place in battle with Athena’s rather different range of war, wisdom and craft." },
  aphrodite: { story: "Aphrodite is the goddess associated with love and desire. Even her beginnings depend on which ancient telling you follow.", detail: "Hesiod describes a sea-foam emergence connected to Uranus. Homer calls her a daughter of Zeus and Dione. These are separate accounts." },
  hermes: { story: "Hermes is a traveller, messenger and trickster, with Zeus and Maia as his parents in Hesiod. His stories move easily between different parts of the divine world.", detail: "The winged herald’s staff is his cue. Maia also opens another branch through Atlas and the Pleiades." },
  dionysus: { story: "Dionysus is associated with wine and revelry. Hesiod names Zeus and Semele as his parents, while other traditions preserve further divine connections.", detail: "Grapes make his seal easy to recognise. Keep an eye on the sources when his story overlaps other underworld traditions." },
  hephaestus: { story: "Hephaestus is the divine smith, associated with metalworking and skilled craft. His family story is one of the places where ancient authors differ.", detail: "Hesiod gives Hera a birth without a partner. Other accounts involve Zeus too, so the two parent sets stay separate." },
  persephone: { story: "Persephone is Demeter’s daughter and queen of the Underworld. Her place between divine families makes her a particularly interesting name to follow in both the myths and the games.", detail: "Her family changes between ancient accounts and Hades continuity. The game’s more revealing origin details remain covered until you choose to uncover them." },
  nyx: { story: "Nyx is Night herself, a primordial divine figure. Her children include beings associated with Sleep, Death, Doom and Strife.", detail: "She is not simply a goddess with a night shift. Night is what she represents, which is why divine categories can overlap." },
  hecate: { story: "Hecate is associated with magic and crossroads. Hesiod names Asteria and Perses as her parents.", detail: "In Hades II she cares for and trains Melinoë. That is a mentorship connection, not a claim that she is Melinoë’s biological mother." },
  melinoe: { story: "Melinoë is an underworld deity invoked in an Orphic hymn and the protagonist reimagined for Hades II. She is a perfect starting point for comparing an ancient figure with a game adaptation.", detail: "The Orphic hymn names Zeus and Persephone. Hades II gives her Hades and Persephone. Same name, a different branch." },
  zagreus: { story: "Zagreus spends the first Hades trying to escape the Underworld and make sense of his family. In Hades II, his sister Melinoë takes the lead.", detail: "Hades II shifts from a brother trying to get out of the Underworld to a sister trying to get her family back." },
  charon: { story: "Charon ferries the dead through the Underworld. His work makes him familiar even when the older sources give us little about his family.", detail: "No ancient parents are established in the passages checked here. Hades II dialogue names Nyx as his mother." },
  thanatos: { story: "Thanatos personifies Death. He belongs among the children of Night in Hesiod and appears in the first Hades.", detail: "He is distinct from Hades, the ruler of the dead. Following both names makes that difference much easier to remember." },
  hypnos: { story: "Hypnos personifies Sleep and belongs to Nyx’s family. His connection with Thanatos puts Sleep and Death on the same remarkable branch.", detail: "The sleeping eye and wing are navigation cues. A personified experience can have a family and a personality in these stories." },
  moros: { story: "Moros personifies Doom and is one of Nyx’s children in Hesiod. Hades II turns that ominous name into someone you can actually get to know.", detail: "Doom, Sleep and Death being relatives is quite a family introduction." },
  nemesis: { story: "Nemesis is associated with retribution and the correction of excess. She is another figure whose abstract role becomes a strong personality in Hades II.", detail: "Her scales are a useful visual cue. The game’s character introduction calls her Retribution Incarnate." },
  eris: { story: "Eris personifies Strife and belongs to Nyx’s family in Hesiod. She makes conflict a character you can encounter rather than just a thing that happens.", detail: "She is another reason the boundary between a god and a personification does not stay neat for very long." },
  "dora-game": { story: "Dora is the friendly shade who shares Melinoë’s tent at the Crossroads. Her conversations gradually suggest that there is more behind her name and personality.", detail: "Her identity connection stays hidden here until you uncover the game spoilers. The seal only shows a shade." },
  "dusa-game": { story: "Dusa is the floating Gorgon custodian in the first Hades. A minor encounter can still make the Underworld feel like a place full of individual lives.", detail: "This entry keeps her game identity separate rather than automatically assigning her another Gorgon’s ancient biography." },
};

const hadesStories: Record<string, string> = {
  aphrodite: "Aphrodite puts the power of love to work in battle. Her blessings leave enemies Weak, and the flirting starts almost as soon as she offers Zagreus help with his escape.",
  apollo: "Apollo helps Melinoë fight with light. His blessings can make her attacks reach farther and leave enemies Dazed, turning the god of music and prophecy into a surprisingly practical ally on a run.",
  ares: "Ares lends Zagreus the power of Doom. An enemy can take a hit, keep fighting for a moment, and then get struck again. The god of war is happy to help if the escape keeps the fighting going.",
  artemis: "Artemis shows up during Melinoë’s journey and sends arrows into the fight. She prefers the hunt to the company of Olympus, and her blessings make a well-placed hit count for much more.",
  athena: "Athena helps Zagreus with blessings that turn enemy attacks back at them. Demeter jokes about Athena springing from Zeus’s head, and Athena takes the jab at her father in stride.",
  chaos: "Chaos remembers a world before Time. Their offers come with a catch. Zagreus or Melinoë has to survive a temporary handicap before the promised reward takes effect.",
  charon: "Charon runs a shop as well as a ferry. Zagreus can spend his obols there, or take money from a sack behind the shop and find out that the quiet boatman is quite capable of collecting a debt.",
  "chronos-hades": "Chronos takes over the House of Hades and makes the Underworld the seat of his war. Melinoë has to confront Time himself, and the arena makes it feel personal when the floor becomes the face of a clock.",
  circe: "Melinoë meets Circe on the way to Olympus, where the witch offers help with the journey. Back at the Crossroads, Odysseus remembers that his own crew spent a whole year on her island.",
  daedalus: "Daedalus did work for the House of Hades. Players see his name on hammers that can change what a weapon actually does, which gives the old craftsman a presence in a fight without putting him in the room.",
  demeter: "Demeter freezes the surface after Persephone disappears. Even Dionysus asks Zagreus to talk her round when the winter threatens his grapes. Her blessings put that same cold to use against enemies.",
  dionysus: "Dionysus would rather keep the party going. When Demeter’s winter threatens the grapes, he asks Zagreus to see if she might ease up. In battle his drink of choice can leave enemies Hangover.",
  "dora-game": "Dora shares Melinoë’s tent at the Crossroads. The shade has a great deal to say about the living for someone who has trouble remembering her own life.",
  "dusa-game": "Dusa is the floating Gorgon custodian in the House of Hades. Zagreus meets her at work, usually in the middle of cleaning up after someone else.",
  eris: "Eris likes to get in the way when Melinoë has somewhere to be. On the road to Olympus she brings the Adamant Rail to the fight, giving Strife a rather loud way to make herself heard.",
  hades: "Hades treats Zagreus’s escape attempts as a problem to be stopped, even if he has to stand guard at the exit himself. In the sequel he finds himself a prisoner in the kingdom he once ruled.",
  harpies: "The Harpies are among the enemies helping Chronos on the surface. He mentions them alongside Polyphemus when he talks about who is on his side.",
  hecate: "Hecate takes Melinoë in after the fall of the House of Hades. At the Crossroads she raises and trains her, then tests whether her student is ready to face what waits below.",
  helios: "When Zagreus meets Demeter, she remarks that Helios has gone a long time without shining on the surface. The missing sun makes her endless winter feel like a world in which even the gods have lost track of the seasons.",
  hephaestus: "Hephaestus lends Melinoë the force of a hammer blow. Some of his blessings give an attack a heavy burst of damage and then make her wait before it can happen again.",
  hera: "Hera makes one enemy share the hurt dealt to another through her Hitch blessing. Her argument with Zeus also makes it into the rules. One of their Duo Boons lets Melinoë trade away Hera’s blessings to strengthen his.",
  heracles: "Heracles turns up on the surface fighting the same enemies as Melinoë. For a little while the legendary hero is simply the other person in the room trying to get through a crowd of monsters.",
  hermes: "Hermes gives Zagreus and Melinoë ways to move and act faster. He also lets slip that he and Charon work together. The ferryman and the messenger have routes of their own through the Underworld.",
  hestia: "Hestia turns hearth fire into a weapon Melinoë can carry with her. A hit can leave an enemy Scorched, so the fire goes on doing damage while Melinoë is already dealing with the next problem.",
  hyperion: "Hyperion belongs to the older generation of Titans. Hera brings him up in conversation, and the Olympians’ memories of the Titans give the current war a past that stretches well beyond Melinoë’s own.",
  hypnos: "Hypnos greets Zagreus after a failed escape and cheerfully offers advice about whatever just killed him. In Hades II, the personification of Sleep ends up giving Melinoë a different sort of problem. He won’t wake up.",
  icarus: "Icarus makes wings of his own after the flight with Daedalus that ended in the sea. When Melinoë runs into trouble in Thessaly, he swoops in to help and offers her one of his inventions.",
  medea: "Medea offers Melinoë curses on the surface. One of them harms enemies as soon as they appear, so a visit to the witch can change the next fight before Melinoë even swings.",
  melinoe: "Melinoë grows up at the Crossroads learning witchcraft from Hecate. To take back the House of Hades, she has to fight her way through the Underworld and take on the Titan who controls Time.",
  moirai: "The Fates decree that Hades will have no heir. Zagreus eventually learns why everyone expected him to die and hears how Nyx helped bring him back, in a story where even a prophecy leaves room for surprises.",
  moros: "Melinoë meets Doom himself through the List of Minor Prophecies. Moros is more thoughtful than his name suggests, and the two talk about what can still be changed when a fate has already been written down.",
  nemesis: "Nemesis sometimes drops into one of Melinoë’s fights and challenges her to see who can defeat more enemies. For the personification of Retribution, even a quick detour can turn into a competition.",
  nyx: "Nyx helps Zagreus leave the House by giving him access to the Mirror of Night. As he learns more about his birth, he discovers she has already helped him in a much bigger way. She brought him back to life and raised him.",
  odysseus: "At the Crossroads, Odysseus helps plan Melinoë’s campaign. He knows what can go wrong on a long journey. When Polyphemus blocks the road to Olympus, the old strategist has a very personal reason to remember that Cyclops.",
  pandora: "At the Crossroads, Melinoë knows Pandora as Dora, the shade who shares her tent. As Dora remembers her life, the memory that comes back is of opening a jar and letting the daemons out.",
  persephone: "Persephone leaves the Underworld and tends a garden on the surface. When Zagreus finally finds her, the meeting is cut short because he cannot stay there for long. He has to make the whole journey again to keep talking to her.",
  "persephone-mortal-father-game": "Persephone says her father was mortal. She speaks about him when explaining her family to Zagreus, and the game leaves him unnamed.",
  "polyphemus-cyclops": "Polyphemus guards the way to Olympus and remembers losing his eye to Odysseus. Poseidon admits he once fooled the Cyclops into believing they were father and son.",
  poseidon: "Poseidon lends Melinoë waves that shove enemies back. He is just as pleased to recount an old prank as he is to help, especially when she discovers the Cyclops blocking the way to Olympus.",
  scylla: "Scylla and the Sirens play as a band in Oceanus. Melinoë has to fight through the performance, while Poseidon remembers when they were already trouble for sailors.",
  selene: "Selene offers Melinoë the Moon’s power through Hexes. They build up as she spends Magick and give her another way to turn a fight, from healing herself to calling down a strike.",
  sirens: "The Sirens perform with Scylla in Oceanus. Their music keeps going during the fight, even as Melinoë tries to take the band apart one member at a time.",
  thanatos: "Thanatos visits Zagreus during escape attempts and turns a room full of enemies into a contest. Whoever gets more kills wins, though the encounters gradually make room for conversations outside the fight.",
  theia: "Theia comes up when Demeter talks to Zagreus about motherhood. Demeter barely knows what to make of the Titan she came from, even as she reflects on the daughter she herself lost.",
  zagreus: "Zagreus keeps trying to escape the Underworld to find Persephone. Every death takes him back to the House, and even when he reaches her garden, he has only a little time to talk before he is pulled back again. The sequel sends Melinoë on a journey in the opposite direction.",
  zeus: "Zeus lends Melinoë his lightning in the fight against Chronos. His Blitz blessing marks an enemy, then calls down a thunderbolt once the enemy has taken enough damage.",
};

const ancientStories: Record<string, string> = {
  aphrodite: "In Hesiod’s tale, Aphrodite rises from sea foam and comes ashore in Cyprus. Eros and Desire follow her as she joins the gods, bringing the power of attraction into a world that has already seen plenty of fighting.",
  apollo: "The Homeric Hymn to Apollo tells how he searches for a place to establish his oracle. At Delphi he kills a great serpent near a spring and makes the site a place where mortals come to ask the god what lies ahead.",
  ares: "In the Iliad, the war god once spends thirteen months trapped in a bronze jar after two giants capture him. Hermes eventually slips him out. It’s an unexpectedly helpless moment for a god who usually makes everyone else afraid.",
  artemis: "In Ovid’s telling, the hunter Actaeon stumbles across Artemis bathing. She turns him into a stag, and his own hunting dogs run him down before he can make them recognise him.",
  asteria: "In Apollodorus, Asteria becomes a quail to escape Zeus and throws herself into the sea. The story links her to the island that would later be called Delos.",
  athena: "When Athena and Poseidon compete to become the patron of Athens, Poseidon strikes the rock and brings up salt water. Athena plants an olive tree. The gods award her the land, and Athens takes her name.",
  chaos: "Hesiod starts with Chaos, the opening before the familiar gods. Night and Darkness come from it, while Gaia, Tartarus, and Eros are named among the other first beings.",
  charon: "Charon ferries travellers into the Underworld. In Aristophanes’ Frogs, Dionysus boards his boat and even has to take an oar while the frogs sing.",
  circe: "In the Odyssey, Circe feeds Odysseus’s crew and turns them into pigs. Hermes gives Odysseus a plant that protects him from the spell. Once he has won his crew back, they stay on her island for a year.",
  daedalus: "Daedalus makes wings out of feathers and wax so he and Icarus can escape Crete. He warns Icarus to keep between the sea and the sun. Daedalus makes it across, but the young man does not.",
  demeter: "When Persephone is taken below, Demeter searches for her and stops the grain from growing. The famine forces Zeus to send Hermes to the Underworld. When Persephone returns, Demeter lets the fields grow again.",
  dionysus: "In a Homeric hymn, pirates seize Dionysus after mistaking him for a wealthy young man. Vines spread across their ship, the god takes the shape of a lion, and the frightened sailors leap overboard and become dolphins.",
  eris: "Eris personifies Strife and is a daughter of Night in Hesiod’s Theogony. She has a whole branch of her own, filled with the troubles that follow conflict.",
  gaia: "Gaia is Earth itself. When Ouranos keeps some of their children shut away inside her, she makes a sickle and asks them to help her. Only Kronos dares to take it, setting the succession of the gods in motion.",
  hades: "After the defeat of the Titans, Hades draws the Underworld as his share of the world. In the Homeric Hymn to Demeter, he takes Persephone below and gives her a pomegranate seed that binds her to return.",
  harpies: "The Argonauts meet Phineus, whose meals are snatched or fouled by the Harpies. The winged sons of the North Wind give chase, and Phineus is finally able to eat in peace.",
  hecate: "Hecate hears Persephone cry out when she is taken. She comes to Demeter carrying torches and goes with her to ask Helios what he saw. When Persephone returns, Hecate becomes her companion.",
  helios: "In the Odyssey, Helios keeps sacred cattle on an island. Odysseus warns his men to leave them alone, but hunger wins out. Helios demands justice, and Zeus destroys their ship with a thunderbolt.",
  hephaestus: "When Achilles needs new armour in the Iliad, Hephaestus forges a shield with a whole world on it. He works cities, fields, dancers, and the ocean into a single object before sending it back to the war.",
  hera: "In the Iliad, Hera wants to give the Greeks a chance to fight back while Zeus is watching over Troy. She borrows Aphrodite’s charms, persuades Sleep to help, and keeps Zeus occupied long enough for Poseidon to intervene.",
  hermes: "In his Homeric hymn, Hermes steals Apollo’s cattle on the day he is born. The two make peace when Apollo hears him play the lyre he made from a tortoise shell. The trade turns a cattle raid into the beginning of a friendship.",
  hestia: "The Homeric Hymn to Aphrodite says Poseidon and Apollo both sought to marry Hestia. She swore to remain unmarried, and Zeus gave her a place of honour at the hearth, at the centre of the home.",
  hypnos: "In the Iliad, Hera asks Hypnos to lull Zeus to sleep so the gods can help the Greeks. He hesitates because he remembers Zeus chasing him the last time he tried it. Only after Hera makes him a better offer does he agree.",
  icarus: "Icarus escapes Crete on wings that Daedalus made from wax and feathers. He climbs higher than his father warned him to, the sun softens the wax, and he falls into the sea.",
  kronos: "Kronos hears that one of his children will overthrow him and swallows each of them at birth. When Zeus is born, Rhea gives him a wrapped stone instead. By the time Kronos learns what happened, the child he missed is ready to challenge him.",
  leto: "In the Homeric Hymn to Apollo, Leto travels from place to place trying to find somewhere to give birth. Delos finally takes her in after she promises that Apollo will build his sanctuary there.",
  "maia-pleiad": "Maia lives in a cave on Mount Cyllene in the Homeric Hymn to Hermes. She warns her newborn that his midnight adventures will get him in trouble, but Hermes has already decided there is more to life than staying in the cave.",
  melinoe: "The Orphic hymn to Melinoë pictures her roaming the earth at night, changing shape and startling mortals. It ends by asking her to send those frightening visions away.",
  metis: "When Zeus is ready to challenge Kronos, Metis gives the Titan a potion that makes him bring up the children he swallowed. Later Zeus swallows Metis herself after hearing a prophecy that her next child could rule in his place.",
  moirai: "In Plato’s Myth of Er, the three Fates sit around the spindle of the cosmos. The souls of the dead choose their next lives, then the Fates set those choices in motion and make them irreversible.",
  moros: "Moros embodies the doom that waits for mortals. Hesiod gives him a place among the forces that emerge from Night, alongside the things people can feel but cannot bargain with, such as Sleep and Death.",
  nemesis: "In Ovid’s story of Narcissus, someone he has spurned asks that he know what it feels like to love without being loved back. Nemesis hears the plea, and Narcissus falls for the one person who can never answer him, his own reflection.",
  nyx: "In the Iliad, Sleep remembers fleeing to Nyx after making Zeus furious. Zeus stops the pursuit rather than offend Night, a small moment that shows just how much weight she carries among the gods.",
  odysseus: "Odysseus spends years trying to get home to Ithaca after the Trojan War. He escapes Polyphemus by calling himself Nobody, then gives away his real name as he sails off. The Cyclops calls on Poseidon, and that last boast helps make the journey home much longer.",
  pandora: "In Hesiod’s Works and Days, Zeus sends Pandora to mortals after Prometheus steals fire for them. Epimetheus accepts the gift despite his brother’s warning. When Pandora opens the jar, troubles escape into the world and Hope stays inside.",
  persephone: "Persephone is gathering flowers when Hades takes her to the Underworld. Demeter’s search brings the growing season to a halt. Persephone eventually returns, but because she ate a pomegranate seed below, she must spend part of each year there.",
  "polyphemus-cyclops": "Polyphemus shuts Odysseus and his crew in a cave and rolls a boulder across the entrance. Odysseus blinds him, then escapes with his men by clinging to the undersides of the Cyclops’s sheep.",
  poseidon: "In the Odyssey, Poseidon makes the voyage home miserable for Odysseus after the hero blinds Polyphemus. Even when Odysseus is close to safety, the sea god can still raise a storm and tear his raft apart.",
  rhea: "Rhea hides her youngest child, Zeus, in Crete. She wraps a stone in swaddling clothes and hands it to Kronos, who swallows it without looking. The trick gives Zeus time to grow up.",
  scylla: "Circe warns Odysseus that sailing close to Scylla means losing six men, but sailing too close to the whirlpool opposite her could cost the whole ship. He takes the narrower loss, and Scylla snatches six sailors from the deck.",
  selene: "Selene is the Moon who crosses the night sky. In the Argonautica, she sees Medea hurrying to meet Jason and remembers how often she herself went to the cave of Endymion, the mortal she loved.",
  semele: "In Ovid, Hera tricks Semele into asking Zeus to appear as he does among the gods. Zeus has sworn to grant her wish. The lightning kills her, but he rescues the unborn Dionysus and carries him to term in his thigh.",
  sirens: "In the Odyssey, the Sirens promise knowledge to anyone who stops to listen. Odysseus plugs his crew’s ears with wax and has them tie him to the mast, so he can hear the song without steering the ship toward it.",
  thanatos: "When Sarpedon falls in the Iliad, Zeus asks Apollo to wash and prepare his body. Thanatos and Hypnos carry him back to Lycia, where his people can bury him.",
  thoosa: "Thoosa appears when Zeus explains why Odysseus is still at sea. The Cyclops Odysseus blinded is her son Polyphemus, and his father Poseidon has made it his business to keep the hero from getting home.",
  typhon: "Hesiod describes Typhon as a many-headed threat to Zeus after the defeat of the Titans. Their battle shakes the earth and boils the sea before Zeus strikes him down with a thunderbolt.",
  uranus: "Ouranos is the sky stretched over Gaia. In Hesiod, he shuts his children inside the Earth until Gaia makes a sickle and Kronos takes it up against him. The struggle ends the reign of the first Sky.",
  zagreus: "Nonnus tells of a young Zagreus born to Zeus and Persephone. He climbs onto Zeus’s throne and takes up the lightning, but the Titans catch him with a mirror and attack. Nonnus tells the story as an earlier life of Dionysus.",
  zeus: "Zeus is the youngest child of the Titans Kronos and Rhea. Rhea hides him and gives Kronos a stone to swallow in his place. Zeus grows up, frees his siblings, and defeats the Titans in the Titanomachy. He draws the sky as his share and reigns over the gods on Mount Olympus.",
};

const roles: Record<string, string> = {
  aphrodite: "Goddess of love and desire", apollo: "God of music and prophecy",
  ares: "God of war", artemis: "Goddess of the hunt", athena: "Goddess of wisdom and war",
  chaos: "The primordial opening", charon: "Ferryman of the dead", "chronos-hades": "Titan of Time",
  demeter: "Goddess of the harvest", dionysus: "God of wine and revelry", eris: "Goddess of strife",
  hades: "God of the Underworld", hecate: "Goddess of magic and crossroads",
  hephaestus: "God of the forge", hera: "Goddess of marriage", hermes: "God of messengers and travellers",
  hestia: "Goddess of the hearth", hypnos: "God of sleep", melinoe: "Goddess of ghosts",
  moirai: "The three Fates", moros: "Doom personified", nemesis: "Goddess of retribution",
  nyx: "Goddess of night", persephone: "Queen of the Underworld", poseidon: "God of the sea",
  selene: "Goddess of the Moon", thanatos: "Death personified", zagreus: "Prince of the Underworld",
  zeus: "God of the sky and thunder",
};

export function mythologyRole(entity: MythologyEntity) {
  const role = roles[entity.id] || entity.qualifier || entity.domains.join(" · ") || entity.categories[0] || "Mythical figure";
  return role[0].toUpperCase() + role.slice(1);
}

export function mythologyStory(entity: MythologyEntity, catalogue: MythologyCatalogue, mode?: "game" | "ancient"): Story {
  const selectedStory = mode === "game" ? hadesStories[entity.id] : mode === "ancient" ? ancientStories[entity.id] : undefined;
  if (selectedStory) return { story: selectedStory, detail: "" };
  if (mode !== "game" && stories[entity.id]) return stories[entity.id];
  const byId = new Map(catalogue.entities.map((item) => [item.id, item]));
  if (mode === "game") {
    const origin = catalogue.lineages.find((claim) => claim.child === entity.id && isGameTradition(claim.tradition));
    const parents = origin?.parents.map((id) => byId.get(id)?.name).filter(Boolean).join(" and ");
    if (parents) return { story: `In the games, ${entity.name} is a child of ${parents}.`, detail: "" };
    const relation = catalogue.relationships.find((claim) => isGameTradition(claim.tradition) && (claim.from === entity.id || claim.to === entity.id));
    return { story: relation?.notes || entity.summary, detail: "" };
  }
  const origin = catalogue.lineages.filter((claim) => claim.child === entity.id && !claim.spoiler && !isGameTradition(claim.tradition)).sort((a, b) => b.parents.length - a.parents.length)[0];
  const group = catalogue.relationships.find((claim) => claim.from === entity.id && claim.type === "member_of" && !claim.spoiler);
  const meaningful = !/appears in the cited|in the cited tradition\.?$|in the cited account\.?$/i.test(entity.summary);
  const relation = origin?.mode === "creation" ? "is generated by" : origin?.mode === "emergence" ? "emerges from" : "is named as a child of";
  const family = origin ? `${entity.name} ${relation} ${origin.parents.map((id) => byId.get(id)?.name || id).join(" and ")} in ${origin.tradition}.` : "";
  const membership = group ? `This entry places ${entity.name} among the ${byId.get(group.to)?.name || group.to}.` : "";
  const role = entity.domains.length ? `${entity.name} is associated with ${entity.domains.join(", ")}.` : `${entity.name} appears in the source as ${entity.kind === "collective" ? "a collective group" : "a named figure"}.`;
  const child = catalogue.lineages.find((claim) => claim.parents.includes(entity.id) && !claim.spoiler && !isGameTradition(claim.tradition));
  const source = catalogue.sources.find((item) => item.id === entity.sourceRefs[0]?.sourceId);
  const continuation = child ? `${byId.get(child.child)?.name || child.child} continues this family branch.` : source ? `This entry follows ${source.author}, ${source.title}.` : role;
  return {
    story: [meaningful ? entity.summary : membership || role, family || continuation].filter(Boolean).join(" "),
    detail: entity.kind === "collective" ? "This seal represents a group. The individual members have their own entries where the sources name them."
      : membership || (origin ? "The cited entry preserves a name and a family connection. The source list below is the place to explore further." : "The checked sources do not establish parents for this entry. An unknown origin stays unknown here."),
  };
}
